def calcular_volume_das_colheitas(apps, schema_editor):
    """Lançamentos existentes: volume = área x rendimento do talhão."""
    Colheita = apps.get_model("sistema", "Colheita")
    InventarioTalhao = apps.get_model("sistema", "InventarioTalhao")
    for colheita in Colheita.objects.select_related("talhao", "inventario"):
        talhao, inventario = colheita.talhao, colheita.inventario
        rendimento = (
            InventarioTalhao.objects.filter(inventario=inventario, talhao=talhao)
            .values_list("volume_ha", flat=True)
            .first()
        )
        if not rendimento and talhao.volume_m3 is not None and talhao.area_ha:
            rendimento = (talhao.volume_m3 / talhao.area_ha).quantize(Decimal("0.001"))
        if not rendimento:
            rendimento = inventario.volume_ha
        colheita.rendimento_m3_ha = rendimento
        if rendimento:
            colheita.volume_m3 = (colheita.area_ha * rendimento).quantize(
                Decimal("0.001")
            )
        colheita.save(update_fields=["rendimento_m3_ha", "volume_m3"])


